Quadrilateral $ABCD$ has been translated to give quadrilateral $EFGH$.
Name the vertex in $EFGH$ that corresponds to $C$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\coordinate (A) at (0,0);
\coordinate (B) at (2.0,0.2);
\coordinate (C) at (2.4,1.4);
\coordinate (D) at (0.4,1.2);
\coordinate (E) at (3.3,0.5);
\coordinate (F) at (5.3,0.7);
\coordinate (G) at (5.7,1.9);
\coordinate (H) at (3.7,1.7);
\draw (A) -- (B) -- (C) -- (D) -- cycle;
\draw (E) -- (F) -- (G) -- (H) -- cycle;
\node[below left] at (A) {$A$};
\node[below right] at (B) {$B$};
\node[above right] at (C) {$C$};
\node[above left] at (D) {$D$};
\node[below left] at (E) {$E$};
\node[below right] at (F) {$F$};
\node[above right] at (G) {$G$};
\node[above left] at (H) {$H$};
\end{tikzpicture}
[/tikz]

$\triangle ABC$ has been rotated to give $\triangle DEF$.
Name the side in $\triangle DEF$ that corresponds to $AC$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\coordinate (A) at (0,0);
\coordinate (B) at (2.4,0);
\coordinate (C) at (2.0,1.3);
\coordinate (D) at (4.2,2.6);
\coordinate (E) at (4.2,0.2);
\coordinate (F) at (5.5,0.6);
\draw (A) -- (B) -- (C) -- cycle;
\draw (D) -- (E) -- (F) -- cycle;
\node[below left] at (A) {$A$};
\node[below right] at (B) {$B$};
\node[above] at (C) {$C$};
\node[above] at (D) {$D$};
\node[below left] at (E) {$E$};
\node[below right] at (F) {$F$};
\end{tikzpicture}
[/tikz]

The triangles are congruent.
Use the matching marks to name the vertex in $\triangle RST$ that corresponds to vertex $K$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{decorations.markings}
\tikzset{
  tickmark/.style={postaction={decorate, decoration={markings,
    mark=at position 0.5 with {\draw[black] (0pt,-4pt) -- (0pt,4pt);}}}},
  tickmark2/.style={postaction={decorate, decoration={markings,
    mark=at position 0.5 with {\draw[black] (-2pt,-4pt) -- (-2pt,4pt);
                               \draw[black] (2pt,-4pt) -- (2pt,4pt);}}}},
  tickmark3/.style={postaction={decorate, decoration={markings,
    mark=at position 0.5 with {\draw[black] (-3pt,-4pt) -- (-3pt,4pt);
                               \draw[black] (0pt,-4pt) -- (0pt,4pt);
                               \draw[black] (3pt,-4pt) -- (3pt,4pt);}}}},
}
\coordinate (J) at (0,0.2);
\coordinate (K) at (1.9,1.6);
\coordinate (L) at (2.5,0);
\coordinate (R) at (6.4,1.5);
\coordinate (S) at (4.5,0.1);
\coordinate (T) at (3.9,1.7);
\draw[tickmark] (J) -- (K);
\draw[tickmark2] (K) -- (L);
\draw[tickmark3] (J) -- (L);
\draw[tickmark] (R) -- (S);
\draw[tickmark2] (S) -- (T);
\draw[tickmark3] (R) -- (T);
\node[below left] at (J) {$J$};
\node[above] at (K) {$K$};
\node[below right] at (L) {$L$};
\node[above right] at (R) {$R$};
\node[below] at (S) {$S$};
\node[above left] at (T) {$T$};
\end{tikzpicture}
[/tikz]

The quadrilaterals are congruent.
$PQRS$ has been reflected to give $WXYZ$.
Name the side in $WXYZ$ that corresponds to side $QR$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\coordinate (P) at (0,1.5);
\coordinate (Q) at (1.2,1.5);
\coordinate (R) at (2.0,0);
\coordinate (S) at (0,0);
\coordinate (W) at (5.6,1.5);
\coordinate (X) at (4.4,1.5);
\coordinate (Y) at (3.6,0);
\coordinate (Z) at (5.6,0);
\draw (P) -- (Q) -- (R) -- (S) -- cycle;
\draw (W) -- (X) -- (Y) -- (Z) -- cycle;
\node[above] at (P) {$P$};
\node[above] at (Q) {$Q$};
\node[below] at (R) {$R$};
\node[below] at (S) {$S$};
\node[above] at (W) {$W$};
\node[above] at (X) {$X$};
\node[below] at (Y) {$Y$};
\node[below] at (Z) {$Z$};
\end{tikzpicture}
[/tikz]

The triangles are congruent.
Use the angle marks to name the angle in $\triangle UVW$ that corresponds to $\angle E$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{angles}
\coordinate (D) at (0,0);
\coordinate (E) at (2.6,0.4);
\coordinate (F) at (1.0,1.8);
\coordinate (U) at (6.3,2.0);
\coordinate (V) at (3.7,1.6);
\coordinate (W) at (5.3,0.2);
\draw (D) -- (E) -- (F) -- cycle;
\draw (U) -- (V) -- (W) -- cycle;
\pic[draw, angle radius=0.45cm] {angle = E--D--F};
\pic[draw, angle radius=0.38cm] {angle = F--E--D};
\pic[draw, angle radius=0.52cm] {angle = F--E--D};
\pic[draw, angle radius=0.45cm] {angle = V--U--W};
\pic[draw, angle radius=0.38cm] {angle = W--V--U};
\pic[draw, angle radius=0.52cm] {angle = W--V--U};
\node[below left] at (D) {$D$};
\node[below right] at (E) {$E$};
\node[above] at (F) {$F$};
\node[above right] at (U) {$U$};
\node[above left] at (V) {$V$};
\node[below] at (W) {$W$};
\end{tikzpicture}
[/tikz]

These two pentagons are congruent. Which angle in $UVWXY$ corresponds to $\angle N$?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\coordinate (K) at (0,0);
\coordinate (L) at (2.8,0);
\coordinate (M) at (2.8,1);
\coordinate (N) at (1.2,1.7);
\coordinate (P) at (0,1.7);
\coordinate (U) at (5.6,0);
\coordinate (V) at (5.6,2.8);
\coordinate (W) at (4.6,2.8);
\coordinate (X) at (3.9,1.2);
\coordinate (Y) at (3.9,0);
\draw (K)--(L)--(M)--(N)--(P)--cycle;
\draw (U)--(V)--(W)--(X)--(Y)--cycle;
\node[below left] at (K) {$K$};
\node[below right] at (L) {$L$};
\node[right] at (M) {$M$};
\node[above] at (N) {$N$};
\node[above left] at (P) {$P$};
\node[below right] at (U) {$U$};
\node[above right] at (V) {$V$};
\node[above left] at (W) {$W$};
\node[left] at (X) {$X$};
\node[below left] at (Y) {$Y$};
\end{tikzpicture}
[/tikz]

Pentagon $KLMNP$ has been reflected to give pentagon $RSTUV$.
Name the vertex in $RSTUV$ that corresponds to $N$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\coordinate (K) at (0,0);
\coordinate (L) at (1.8,0);
\coordinate (M) at (1.8,0.9);
\coordinate (N) at (0.5,1.7);
\coordinate (P) at (0,0.9);
\coordinate (R) at (5.6,0);
\coordinate (S) at (3.8,0);
\coordinate (T) at (3.8,0.9);
\coordinate (U) at (5.1,1.7);
\coordinate (V) at (5.6,0.9);
\draw (K)--(L)--(M)--(N)--(P)--cycle;
\draw (R)--(S)--(T)--(U)--(V)--cycle;
\node[below left] at (K) {$K$};
\node[below right] at (L) {$L$};
\node[right] at (M) {$M$};
\node[above] at (N) {$N$};
\node[left] at (P) {$P$};
\node[below right] at (R) {$R$};
\node[below left] at (S) {$S$};
\node[left] at (T) {$T$};
\node[above] at (U) {$U$};
\node[right] at (V) {$V$};
\end{tikzpicture}
[/tikz]
